package com.cgi.addagent;
import com.cgi.addagent.mcp.McpServer; import com.cgi.addagent.model.*; import com.cgi.addagent.parser.*; import com.cgi.addagent.router.*; import com.cgi.addagent.extractor.*; import com.cgi.addagent.generator.*; import com.cgi.addagent.writer.*;
import java.util.*;
public class Main {
 public static void main(String[] args)throws Exception{if(args.length==0){help();return;}if(Arrays.asList(args).contains("--mcp")){new McpServer().start();return;}if(Arrays.asList(args).contains("--interactive")){interactive();return;}Map<String,String>a=parse(args);String add=a.get("--add"),out=a.get("--output"),mode=a.getOrDefault("--mode","ALL"),module=a.getOrDefault("--module","ALL");if(add==null||out==null){help();return;}ProjectConfig c=ProjectConfig.defaults();List<Paragraph> ps=new DocParser().parse(add);SectionRouter r=new SectionRouter();Map<String,List<Paragraph>> fe=r.routeFeSections(ps),be=r.routeBeSections(ps);ModuleExtractor ex=new ModuleExtractor();CodeFileWriter w=new CodeFileWriter();for(var e:be.entrySet())if(("ALL".equalsIgnoreCase(module)||SectionRouter.normalise(e.getKey()).equals(SectionRouter.normalise(module)))&&!"FE".equalsIgnoreCase(mode))w.write(out,"BE",e.getKey(),new BeCodeGenerator().generate(ex.extract(e.getKey(),"BE",e.getValue()),c));for(var e:fe.entrySet())if(("ALL".equalsIgnoreCase(module)||SectionRouter.normalise(e.getKey()).equals(SectionRouter.normalise(module)))&&!"BE".equalsIgnoreCase(mode))w.write(out,"FE",e.getKey(),new FeCodeGenerator().generate(ex.extract(e.getKey(),"FE",e.getValue()),c));}
 private static Map<String,String> parse(String[] a){Map<String,String>m=new HashMap<>();for(int i=0;i<a.length;i++)if(a[i].startsWith("--")&&i+1<a.length&&!a[i+1].startsWith("--"))m.put(a[i],a[++i]);return m;}
 private static void interactive(){Scanner s=new Scanner(System.in);System.out.print("ADD path: ");String add=s.nextLine();System.out.print("Output: ");String out=s.nextLine();System.out.print("Mode (BE/FE/ALL): ");String mode=s.nextLine();try{main(new String[]{"--add",add,"--output",out,"--mode",mode,"--module","ALL"});}catch(Exception e){System.err.println(e.getMessage());}}
 private static void help(){System.out.println("ADD Code Agent\nUsage: java -jar add-code-agent.jar --add <docx/docm> --output <dir> [--mode BE|FE|ALL] [--module <name>|ALL] [--interactive] [--mcp]");}
}
